package io.github.sammeeeeeeee.onenet

/** Glyphs shared by the tile and the panel; generated by tools/gen_icons.py. */
object Icons {

    private val WIFI = intArrayOf(
        R.drawable.ic_qs_wifi_0, R.drawable.ic_qs_wifi_1, R.drawable.ic_qs_wifi_2,
        R.drawable.ic_qs_wifi_3, R.drawable.ic_qs_wifi_4,
    )
    private val WIFI_NO_INTERNET = intArrayOf(
        R.drawable.ic_qs_wifi_no_internet_0, R.drawable.ic_qs_wifi_no_internet_1,
        R.drawable.ic_qs_wifi_no_internet_2, R.drawable.ic_qs_wifi_no_internet_3,
        R.drawable.ic_qs_wifi_no_internet_4,
    )
    /** [level] is 0..4. */
    fun wifi(level: Int, noInternet: Boolean = false) =
        (if (noInternet) WIFI_NO_INTERNET else WIFI)[level.coerceIn(0, 4)]

    /** One UI's mobile data arrows; dimmed when data is off or out of service. */
    fun data(noInternet: Boolean = false, off: Boolean = false) = when {
        off -> R.drawable.ic_qs_data_off
        noInternet -> R.drawable.ic_qs_data_no_internet
        else -> R.drawable.ic_qs_data
    }

    /** Frames of the searching animation, in order. */
    val WIFI_SEARCH = intArrayOf(
        R.drawable.ic_qs_wifi_search_0, R.drawable.ic_qs_wifi_search_1, R.drawable.ic_qs_wifi_search_2,
        R.drawable.ic_qs_wifi_search_3, R.drawable.ic_qs_wifi_search_4, R.drawable.ic_qs_wifi_search_5,
    )
}
